// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;

    function setUp() public { c = new Roulette{value: 10 ether}(); }

    // fuzz the caller private key (so we get an address) and a flag that chooses whether the recipient reverts
    function testFuzz_property(uint256 callerKey, bool willRevert) public {
        callerKey = bound(callerKey, 1, 115792089237316195423570985008687907852837564279074904382605163141518161494336);
        // keep callerKey in a reasonable domain but allow wide search
        vm.assume(callerKey != 0);
        address caller = vm.addr(callerKey);
        vm.deal(caller, 20 ether);

        // Deploy a helper that will act as msg.sender for the fallback call and either revert on receive
        // or accept and record the value it got. We need to observe what c did (its balance) after the call.
        AttackerHelper helper = new AttackerHelper(willRevert, address(c));

        // We must arrange conditions so the special branch in C runs: block.number % 15 == 0
        // and block.timestamp > pastBlockTime. pastBlockTime initially 0, so timestamp > 0 holds if timestamp >=1.
        // Warp to ensure timestamp > 0 and roll block to a number divisible by 15.
        vm.warp(1);
        // choose a block number divisible by 15
        uint256 targetBlock = 15 * ((block.number / 15) + 1);
        vm.roll(targetBlock);

        // Now perform the low-level call that triggers fallback with exactly 10 ether, from the helper address.
        vm.prank(address(helper));
        // Ensure helper has funds to pay the call value to c
        vm.deal(address(helper), 10 ether);

        bool ok;
        // Call c's payable fallback by using a low-level call from the helper instance.
        // We perform it via helper calling c; helper will be msg.sender in c and will either revert in its receive()
        // or accept the funds. The try/catch captures whether the call succeeded.
        try helper.callC{value: 10 ether}() {
            ok = true;
        } catch {
            ok = false;
        }

        // GENERAL RULE (single assertion): For the correct contract, after a successful fallback invocation
        // that follows the branch (block.number % 15 == 0), the contract's balance should be 0.
        // This will hold for all inputs on the reference, but the mutant using send(...) can leave balance > 0
        // when the recipient reverts (willRevert == true). We assert that when the call returned succesfully
        // (ok == true) the contract's balance is zero. This is the single assert required.
        assertTrue(!ok || address(c).balance == 0);
    }
}

// Helper that either reverts on receive or accepts; it also exposes a function to call c so that
// c sees this helper as msg.sender. The helper's receive() will revert when willRevert==true.
contract AttackerHelper {
    bool public willRevert;
    address public target;
    constructor(bool _willRevert, address _target) payable {
        willRevert = _willRevert;
        target = _target;
    }
    // When this helper receives ether (as a result of c transferring back), optionally revert to simulate failing recipient.
    receive() external payable {
        if (willRevert) revert("I revert on receive");
        // otherwise accept funds
    }
    // Call C's fallback by sending exactly 10 ether with empty calldata
    function callC() external payable {
        (bool s, ) = target.call{value: msg.value}("");
        require(s, "call failed");
    }
}
